/// <summary>
///
/// </summary>
/// <returns></returns>
public identifierName lastValueElementName()
{
    identifierName ret = classStr(MobConsolidateOrderCreate);


    return ret;
}

public void initParmDefault()

{
    Query query;
    QueryBuildDataSource    qbd;
    QueryBuildRange			qbr;


    super();
    /*if (designTable.PackedQuery != conNull())
    {
        queryRun = new QueryRun(designTable.PackedQuery);
        return;
    }*/
    query = new Query();
    qbd = query.addDataSource(tableNum(WMSPickingRoute));
    qbr = qbd.addRange(fieldNum(WMSPickingRoute,expeditionStatus));
    qbr.value(queryValue(WMSExpeditionStatus::Registered) + ',' + queryValue(WMSExpeditionStatus::Activated) + ',' + queryValue(WMSExpeditionStatus::Started));     
    //qbr.status(1);

    qbd.addRange(fieldNum(WMSPickingRoute,DlvDate)).Value('(DayRange(0,2))');


    queryRun = new QueryRun(query);
}

public static void Main(Args _args)
{
    MobConsolidateOrderCreate creator = new MobConsolidateOrderCreate();
    MobConsolidatedPickingRoutes route;
    if (_args.parm() == 'Add')
    {
        route = _args.record();
        creator.parmRouteID(route.ConsolidatedPickingRouteId);
    }
    if (creator.prompt())
    {
        creator.run();
    }

    //_args.callerFormControl().dataSourceObject().executeQuery();
}

public WMSPickingRouteID parmRouteID(WMSPickingRouteID _useRouteId = useRouteId)
{
    useRouteId = _useRouteId;
    return useRouteId;
}

