/// <summary>
///
/// </summary>
public void run()
{

    Query						q;
    WMSPickingRoute				record;
    //Set							records = new Set(Types::Record);
    //XML							xml;
    NumberSeq num = NumberSeq::newGetNum(WMSParameters::numRefWMSPickingRouteId());
    MobConsolidatedPickingRoutes		header;
    MobConsolidatedPickingRouteOrders	lines;

    super();
    q = queryRun.Query();
    q.name(classStr(MobConsolidateOrderCreate));
    if (useRouteId && MobConsolidatedPickingRoutes::Exists(useRouteId))
    {
        header = MobConsolidatedPickingRoutes::Find(useRouteId);
    }
    else
    {
        header.ConsolidatedPickingRouteId = useRouteId ? useRouteId  : num.num();
        num.used();
        header.insert();
    }
    while (queryRun.next())
    {
        record = queryRun.get(tableNum(WMSPickingRoute));

        if (MobConsolidatedPickingRouteOrders::Exists(record.pickingRouteID))
        {
            continue;
        }

        lines.PickingRouteID = record.pickingRouteID;
        lines.ConsolidatedPickingRouteId = header.ConsolidatedPickingRouteId;
        lines.insert();

    }

}
